  ('bakarkhani', 'বাকরখানি', 'Bakarkhani', 'পুরান ঢাকার মোটা, মচমচে স্তরওয়ালা রুটি, চা বা তরকারির সঙ্গে খাওয়া হয়।', 'A thick, crisp layered flatbread from old Dhaka, enjoyed with tea or curry.', 'pitha_snacks', 'regional', 'Dhaka', 'ঢাকা', 'Dhaka', 10, 'images/foods/bakarkhani.jpg', 'Bakarkhani at puran dhaka 5.jpg — Wasiul Bahar (CC BY-SA 4.0), via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Bakarkhani_at_puran_dhaka_5.jpg', 'unverified', 'medium'),
  ('faridpur-khejur-gur', 'খেজুরের গুড়', 'Date Palm Jaggery', 'শীতকালে খেজুর গাছের রস থেকে তৈরি মিষ্টি গুড়।', 'Sweet jaggery made from date palm sap in winter.', 'sweets_desserts', 'regional', 'Faridpur', 'ফরিদপুর', 'Dhaka', 10, 'images/foods/faridpur-khejur-gur.jpg', 'Traditional way of making Khejur Gur (date palm jaggery) at Gangasagar 01.jpg — Goutam1962 (CC BY-SA 4.0), via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Traditional_way_of_making_Khejur_Gur_(date_palm_jaggery)_at_Gangasagar_01.jpg', 'unverified', 'medium'),
  ('gazipur-kathal', 'কাঁঠাল', 'Jackfruit', 'বাংলাদেশের জাতীয় ফল, সুগন্ধি ও মিষ্টি; গাজীপুরে প্রচুর পাওয়া যায়।', 'The sweet, fragrant national fruit of Bangladesh, plentiful in Gazipur.', 'regional_specialties', 'regional', 'Gazipur', 'গাজীপুর', 'Dhaka', 10, 'images/foods/gazipur-kathal.jpg', 'Jackfruit Flesh.jpg — Mullookkaaran (CC BY-SA 3.0), via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Jackfruit_Flesh.jpg', 'unverified', 'medium'),
  ('gopalganj-chhana-jilapi', 'ছানার জিলাপি', 'Chhana Jilapi', 'ছানা থেকে তৈরি রসে ভেজা মিষ্টি জিলাপি।', 'A syrupy sweet jilapi made from fresh milk curd (chhana).', 'sweets_desserts', 'regional', 'Gopalganj', 'গোপালগঞ্জ', 'Dhaka', 10, 'images/foods/gopalganj-chhana-jilapi.jpg', 'Food-chhanar-jilipi.jpg — Sumit Surai (CC BY-SA 3.0), via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Food-chhanar-jilipi.jpg', 'unverified', 'medium'),
  ('kishoreganj-nakshi-pitha', 'নকশি পিঠা', 'Nakshi Pitha', 'হাতে নকশা করা চালের গুঁড়ার সুন্দর পিঠা।', 'A decorative, hand-patterned rice-flour pitha.', 'pitha_snacks', 'regional', 'Kishoreganj', 'কিশোরগঞ্জ', 'Dhaka', 10, 'images/foods/kishoreganj-nakshi-pitha.jpg', 'Nakshi pitha.jpg — NK Roktim (CC BY-SA 4.0), via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Nakshi_pitha.jpg', 'unverified', 'medium'),
  ('madaripur-rasgulla', 'রসগোল্লা', 'Rasgulla', 'হালকা চিনির রসে ভেজা নরম, স্পঞ্জের মতো ছানার গোল্লা।', 'Soft, spongy cheese balls soaked in light sugar syrup.', 'sweets_desserts', 'regional', 'Madaripur', 'মাদারীপুর', 'Dhaka', 10, 'images/foods/madaripur-rasgulla.jpg', 'One plate rosogulla (এক প্লেট রসগোল্লা).jpg — HridoyKundu (CC BY-SA 4.0), via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:One_plate_rosogulla_(%E0%A6%8F%E0%A6%95_%E0%A6%AA%E0%A7%8D%E0%A6%B2%E0%A7%87%E0%A6%9F_%E0%A6%B0%E0%A6%B8%E0%A6%97%E0%A7%8B%E0%A6%B2%E0%A7%8D%E0%A6%B2%E0%A6%BE).jpg', 'unverified', 'medium'),
